p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chkl_c:		; call chkl (normal)
			pop hl			; got
			ld de, var_chkl_got
			ld bc, 4
			ldir
			pop hl			; want
			ld de, var_chkl_want
			ld bc, 4
			ldir
			ld (p_chkl_rs), sp
			ld sp, p_chkl
			jp ntc_xn
